let message = `👤 <b>แจ้งเตือนสมาชิกใหม่ (New Signup)</b>
━━━━━━━━━━━━━━━━━━

<b>👤 ชื่อ:</b> <code>${fullName}</code>
<b>📧 อีเมล:</b> <code>${email}</code>
<b>⏰ เวลา:</b> ${new Date().toLocaleString("th-TH")}

<i>💬 ตอบกลับข้อความนี้ด้วยคำว่า <b>"agent"</b> หรือ <b>"อนุมัติ"</b> เพื่อปรับบทบาททันทีครับ</i>`;

const alertMsg = `🔔 ลูกค้าสมัครรับข่าวสารใหม่ทางเว็บไซต์!

LINE ID: ${trimmedLineId}
บันทึกข้อมูลเข้าระบบเรียบร้อยแล้ว`;

caption: `🏡 ${input.title}
📍 ทำเล: ${input.popularArea || ""} ${input.province || ""}
💰 ราคา: ${input.rentalPrice ? `฿${input.rentalPrice.toLocaleString()}/เดือน` : input.price ? `฿${input.price.toLocaleString()}` : "ติดต่อสอบถาม"}

📲 สแกน QR Code ในรูปภาพเพื่อดูรูปเพิ่มเติมและติดต่อ Agent ได้เลยครับ!`,

const message = `🎊 <b>ปิดดีลเรียบร้อย! (${dealType})</b>
━━━━━━━━━━━━━━━━━━

<b>🏢 ทรัพย์:</b> ${existing.title}
<b>🔍 รหัส:</b> <code>${existing.id}</code>

<i>ยินดีด้วยกับเอเยนต์ผู้ดูแลเคสนี้ครับ! 🎉</i>`;

const fullCaptionText = `${caption}

${hashtags.join(" ")}

👉 ดูรูปเพิ่มเติม & พิกัด: ${propertyUrl}`;

const fullCaptionText = `${caption}

${hashtags.join(" ")}

👉 ดูข้อมูลเพิ่มเติม: ${propertyUrl}`;

const fullText = `${caption}

${hashtags.join(" ")}

👉 ดูข้อมูลเพิ่มเติม: ${propertyUrl}`;

const plainTextForLine = `🔔 ${title}

${message}${detailLink ? `

ดูรายละเอียดในระบบ CRM: ${detailLink}` : ""}`;

`🛡️ <b>แจ้งเตือนการเข้าสู่ระบบ</b>

พบบัญชีของคุณเข้าใช้งานระบบ CRM เมื่อเวลา <code>${time}</code>

<b>อุปกรณ์:</b> ${metadata?.userAgent || "Unknown"}
<b>พิกัด:</b> ${metadata?.location || "Unknown"}

<i>หากไม่ใช่คุณ กรุณาเปลี่ยนรหัสผ่านทันทีครับ</i>`,
